async function publishModule(name, button) {
  const original = button.textContent;
  button.disabled = true;
  try {
    button.textContent = "Saving settings…";
    await saveSettings(settingsForm);
    button.textContent = "Publishing…";
    const result = await api(`api/guilds/${state.activeGuild.id}/${name}/publish`, { method: "POST" });
    notice(result.url ? "Published successfully in Discord. Open the configured channel to see it." : "Published successfully in Discord.");
  } catch (error) {
    notice(error.message, true);
  } finally {
    button.disabled = false;
    button.textContent = original;
  }
}
